const TOOL_NAME_REGEX=/^[A-Za-z0-9._-]{1,128}$/;export function validateToolName(o){const s=[];if(0===o.length)return{isValid:!1,warnings:["Tool name cannot be empty"]};if(o.length>128)return{isValid:!1,warnings:[`Tool name exceeds maximum length of 128 characters (current: ${o.length})`]};if(o.includes(" ")&&s.push("Tool name contains spaces, which may cause parsing issues"),o.includes(",")&&s.push("Tool name contains commas, which may cause parsing issues"),(o.startsWith("-")||o.endsWith("-"))&&s.push("Tool name starts or ends with a dash, which may cause parsing issues in some contexts"),(o.startsWith(".")||o.endsWith("."))&&s.push("Tool name starts or ends with a dot, which may cause parsing issues in some contexts"),!TOOL_NAME_REGEX.test(o)){const n=o.split("").filter(o=>!/[A-Za-z0-9._-]/.test(o)).filter((o,s,n)=>n.indexOf(o)===s);return s.push(`Tool name contains invalid characters: ${n.map(o=>`"${o}"`).join(", ")}`,"Allowed characters are: A-Z, a-z, 0-9, underscore (_), dash (-), and dot (.)"),{isValid:!1,warnings:s}}return{isValid:!0,warnings:s}}export function issueToolNameWarning(o,s){if(s.length>0){console.warn(`Tool name validation warning for "${o}":`);for(const o of s)console.warn(`  - ${o}`);console.warn("Tool registration will proceed, but this may cause compatibility issues."),console.warn("Consider updating the tool name to conform to the MCP tool naming standard."),console.warn("See SEP: Specify Format for Tool Names (https://github.com/modelcontextprotocol/modelcontextprotocol/issues/986) for more details.")}}export function validateAndWarnToolName(o){const s=validateToolName(o);return issueToolNameWarning(o,s.warnings),s.isValid}